      "summary": "首页 > 科研进展 传统观点认为，多年冻土 消融会激活长期封存的有机碳，部分经由河流以二氧化碳形式向大气释放，加剧全球变暖。 近日，中国科学院青藏高原研究所等组成的联合科研团队提出了新视角。研究提出， 多年冻土融化会加剧二氧化碳释放，也会加速岩石的自然风化过程； 岩石风化可吸收一部分二氧化碳，形成一个以前被忽视的天然“",
