      "matchedTopic": "科学前沿动态",
      "rawText": "首页 > 党建与科学文化 > 工作动态 6月18日，中国科学院沈阳分院分党组召开树立和践行正确政绩观学习教育 第四期 读书班暨理论学习中心组集体扩大学习会。 会上，沈阳分院分党组成员依次领学《习近平关于树立和践行正确政绩观论述摘编》相关篇目、《习近平总书记地方工作期间坚持正确政绩观生动实践》相关内容。 会议提出，读书班坚持读原著学原文悟原理，深入学习领会习近平总书记关于树立和践行正确政绩观的重要论述，进一步深化了思想认识、增强了行动自觉。 会议对下一阶段工作提出要求。一是要持续深刻理解和精准把握正确政绩观的核心内涵，深刻认识党的性质宗旨，更好围绕国家战略推进科技创新；二是要深刻把握科研院所存在的问题，从党性上剖析根源、分析原因，切实做到以案为鉴；三是要压紧压实各级责任，推动学习教育走深走实，坚持目标导向、问题导向，将学习成果转化为推动联系单位服务国家战略、抢占科技制高点的实效实绩。 沈阳分院分党组书记、院长毛志远主持会议，副院长、分党组成员徐岩，分党组副书记杨宏，纪检组组长、分党组成员李明参加会议。分院机关各部门负责人、党委委员和纪委委员列席会议。 6月18日，中国科学院沈阳分院分党组",
