      "rawText": "首页 > 党建与科学文化 > 工作动态 6月16日，中国科学院成都山地灾害与环境研究所召开党委理论学习中心组学习研讨（扩大）会。党委委员、纪委委员，科研、管理、支撑各部门负责人，党支部（总支）书记参加会议。 会议由党委书记谭多财主持。 会议以时间线为脉络，系统学习了十八大以来习近平总书记关于中国科学院重要指示批示。谭多财在领学时强调，十八大以来习近平总书记关于中国科学院重要指示批示，为研究所明确自身职能定位和职责使命，建设国家战略科技力量提供了根本遵循；总书记关于第二次青藏科考、“一带一路”科技创新和极地工作的重要指示批示，为资源环境领域科研工作指明了前进方向；党员领导干部要持续深化学习领会，扎实推进树立和践行正确政绩观学习教育，切实做到学思用贯通、知信行合一。 会议集中学习研讨了习近平总书记在加强基础研究座谈会上的重要讲话和在中共中央政治局第二十五次集体学习时的讲话精神，党委委员赵伟、灾害中心总支副书记杨宗佶作了重点发言。会议强调，基础研究是整个科学体系的源头、是所有技术问题的总机关，防灾减灾救灾是研究所的特色研究阵地；总书记的两次讲话，为研究所采取有效措施加强基础科学研究、凝聚科研",
